\begin{tikzpicture}
\begin{axis}[
    width=0.74\textwidth,
    height=0.46\textwidth,
    xmin=0, xmax=5,
    ymin=0, ymax=35,
    axis lines=left,
    xlabel={\(t\)},
    ylabel={output},
    xtick={0,1,2,3,4,5},
    ytick={0,5,10,20,30},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    legend style={at={(0.02,0.98)},anchor=north west,legend columns=1,font=\small}
]
\addplot[thick, domain=0:5, samples=2] {4+4*x};
\addlegendentry{linear: \(4+4t\)}
\addplot[thick, dashed, domain=0:5, samples=100] {4*1.5^x};
\addlegendentry{exponential: \(4(1.5)^t\)}
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.76\textwidth,
    height=0.45\textwidth,
    xmin=0, xmax=60,
    ymin=0, ymax=40,
    axis lines=left,
    xlabel={\(t\) (seconds)},
    ylabel={\(H(t)\) (meters)},
    xtick={0,7.5,15,22.5,30,45,60},
    xticklabels={\(0\),\(7.5\),\(15\),\(22.5\),\(30\),\(45\),\(60\)},
    ytick={2,20,38},
    yticklabels={\(2\),\(20\),\(38\)},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[thick, domain=0:60, samples=200] {20+18*sin(deg(pi*x/15))};
\addplot[dashed, domain=0:60, samples=2] {20};
\node[fill=white, inner sep=1.5pt, anchor=south] at (axis cs:42,22.2) {midline \(H=20\)};
\node[anchor=south] at (axis cs:7.5,38) {top};
\node[anchor=south west] at (axis cs:23.8,3.8) {bottom};
\end{axis}
\end{tikzpicture}
